  openExternalEditor() {
    const editorCmd = process.env.VISUAL || process.env.EDITOR;
    if (!editorCmd) {
      this.showWarning("No editor configured. Set $VISUAL or $EDITOR environment variable.");
      return;
    }
    const currentText = this.editor.getExpandedText?.() ?? this.editor.getText();
    const tmpFile = path12.join(os9.tmpdir(), `pi-editor-${Date.now()}.pi.md`);
    try {
      fs10.writeFileSync(tmpFile, currentText, "utf-8");
      this.ui.stop();
      const [editor, ...editorArgs] = editorCmd.split(" ");
      const result = spawnSync9(editor, [...editorArgs, tmpFile], {
        stdio: "inherit",
        shell: process.platform === "win32"
      });
      if (result.status === 0) {
        const newContent = fs10.readFileSync(tmpFile, "utf-8").replace(/\n$/, "");
        this.editor.setText(newContent);
      }
    } finally {
      try {
        fs10.unlinkSync(tmpFile);
      } catch {}
      this.ui.start();
      this.ui.requestRender(true);
    }
  }
